mapper.select:
SELECT AVG(a.dur) FROM (
    SELECT  AS dur
    FROM flow_instance a
    WHERE a.del_flag = '0'
    AND a.flow_status IN ('2', '3', '8')
    AND a.update_time IS NOT NULL AND a.create_time IS NOT NULL
    AND a.create_time >= #{timeStart}
    AND a.create_time <= #{timeEnd}
) a

SELECT AVG(a.dur) AS avgDwellSeconds, COUNT(*) AS sampleCount FROM (
    SELECT  AS dur
    FROM flow_his_task a
    WHERE a.del_flag = '0'
    AND a.definition_id = #{definitionId}
    AND a.node_code = #{nodeCode}
    AND a.skip_type = 'PASS'
    AND a.update_time IS NOT NULL AND a.create_time IS NOT NULL
) a
